        <div class="grid gap-4 lg:grid-cols-2">
            <section class="overflow-hidden rounded-xl border border-gray-200 bg-white"><div class="border-b border-gray-200 bg-gray-50 p-4"><div class="flex items-center justify-between gap-3"><h3 class="text-sm font-semibold text-gray-900">Cari Course</h3><span class="text-xs text-gray-500" x-text="meta.total + ' ditemukan'"></span></div><input type="search" x-model="query" @input.debounce.350ms="loadCourses(1)" class="mt-3 w-full rounded-lg border-gray-300 text-sm focus:border-bass-red focus:ring-bass-red" placeholder="Ketik judul course..."></div>
                <div class="relative min-h-72"><div x-show="loading" class="absolute inset-0 z-10 flex items-center justify-center bg-white/80"><span class="text-sm font-medium text-gray-500">Memuat course...</span></div><div x-show="errorMessage" x-cloak class="m-4 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700" x-text="errorMessage"></div><div x-show="!loading && courses.length === 0 && !errorMessage" x-cloak class="flex min-h-72 items-center justify-center p-6 text-center text-sm text-gray-500">Tidak ada course yang cocok.</div><ul x-show="courses.length > 0" class="divide-y divide-gray-100"><template x-for="course in courses" :key="course.id"><li class="flex items-center justify-between gap-3 p-4"><div class="min-w-0"><p class="truncate text-sm font-semibold text-gray-900" x-text="course.title"></p><p class="mt-0.5 text-xs text-gray-500" x-text="course.priceLabel"></p></div><button type="button" @click="addCourse(course)" :disabled="isSelected(course.id)" class="shrink-0 rounded-lg border px-3 py-1.5 text-xs font-semibold disabled:cursor-not-allowed disabled:border-gray-200 disabled:bg-gray-100 disabled:text-gray-400" :class="isSelected(course.id) ? '' : 'border-bass-red text-bass-red hover:bg-red-50'" x-text="isSelected(course.id) ? 'Terpilih' : 'Tambah'"></button></li></template></ul></div>
