@push('scripts')<script>
function learningPathCoursePicker() { return {
    endpoint: @js(route('admin.learning-paths.course-options')), selected: @js($initialCourses), courses: [], query: '', loading: false, errorMessage: '', requestNumber: 0, meta: { currentPage: 1, lastPage: 1, total: 0 },
    async loadCourses(page = 1) { const requestNumber = ++this.requestNumber; this.loading = true; this.errorMessage = ''; try { const url = new URL(this.endpoint, window.location.origin); url.searchParams.set('page', page); if (this.query.trim()) url.searchParams.set('q', this.query.trim()); const response = await fetch(url, { headers: { Accept: 'application/json' } }); if (!response.ok) throw new Error(); const result = await response.json(); if (requestNumber !== this.requestNumber) return; this.courses = result.data; this.meta = result.meta; } catch (error) { if (requestNumber !== this.requestNumber) return; this.courses = []; this.meta = { currentPage: 1, lastPage: 1, total: 0 }; this.errorMessage = 'Course gagal dimuat. Silakan coba lagi.'; } finally { if (requestNumber === this.requestNumber) this.loading = false; } },
    isSelected(id) { return this.selected.some(course => Number(course.id) === Number(id)); }, addCourse(course) { if (!this.isSelected(course.id)) this.selected.push({ ...course }); }, removeCourse(index) { this.selected.splice(index, 1); }, moveCourse(index, direction) { const target = index + direction; if (target < 0 || target >= this.selected.length) return; const [course] = this.selected.splice(index, 1); this.selected.splice(target, 0, course); }
}; }
</script>@endpush
